+    bind(test_mark_word);
+  }
+  andi(temp_reg, temp_reg, tst_bit);
+  if (jmp_set) {
+    bnez(temp_reg, jmp_label, /* is_far */ true);
+  } else {
+    beqz(temp_reg, jmp_label, /* is_far */ true);
+  }
